+			offerId?: string;
+			input?: string;
+			msSinceExposed?: number;
+	  }
+	| {
+			type: "send";
+			candidateId: string;
+			offerId?: string;
+			input?: string;
+			msSinceExposed?: number;
+	  }
+	| { type: "reroll"; offerId?: string; input?: string; cause?: string }
+	| { type: "exposed"; offerId?: string; candidateId?: string }
+	| { type: "hide"; scope?: "chat" }
