+						v: LABEL_SCHEMA_VERSION,
+						at: new Date(this.now()).toISOString(),
+						sessionId: this.options.sessionId,
+						...(action.offerId ? { offerId: action.offerId } : {}),
+						...(this.lastTurn
+							? {
+									turnKey: this.lastTurn.turnKey,
+									runCount: this.lastTurn.runCount,
+								}
+							: {}),
+					};
