+
+	private resolveOffer(
+		state: TurnState | undefined,
+		offerId: string | undefined,
+	): OfferedSet | undefined {
+		if (!state) return undefined;
+		if (!offerId) return this.shown;
+		return state.offers.findLast((offer) => offer.offerId === offerId);
+	}
