+		const cwd = env.workspaceRoot ?? env.cwd ?? ".";
+		const [signedIn, connections] = await Promise.all([
+			this.deps.gh.isAvailable(cwd).catch(() => false),
+			this.deps.connections(),
+		]);
+		this.detection = {
+			routes: githubRoutes(signedIn, connections),
+			detectedAt: this.now(),
+		};
